head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gViewerStat = "P"; // 처리시 뷰=P,  조회시 뷰=R
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.vScrenID = 'ULDSTF10970.xml'; //주권공시처리현황

scwin.search_yn = false;
scwin.isAlarm = true; //알람 상태가 on/off인지 체크 
scwin.isBondsTeam = false; //채권상장공시팀인지 체크
scwin.alarmCnt = 0;
scwin.gMoveToPosition = 0;
scwin.arrOPEN = [0, 1, 2];
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 현재날짜 셋팅	
    scwin.gDate = $c.ut.cGetToday("yyyymmdd");
    edt_SrchDay.setValue(scwin.gDate);
};
scwin.fn_Init = function() {
    for (var i = 0; i < scwin.arrOPEN.length; i++) {
        eval("checkbox_OPEN" + scwin.arrOPEN[i]).setValue(1);
    }
};
scwin.fn_StartSearch = function() {
    scwin.setAlarm();
    scwin.fn_InitSearch();
};
scwin.fn_InitSearch = function() {
    scwin.fn_Reload('N');
};
scwin.fn_Reload = function(pReload) {
    fn_CheckCond(pReload);
    setTimeout("fn_Reload('Y')", 60000); // 1초 = 1000 , 30초 = 30000
    scwin.alarmCnt++;

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !검색--;
사용자;
클릭-- > function(pReload) {
    scwin.gDate = $c.stf.getObjectValue(edt_SrchDay);
    scwin.fn_SearchAlarm(pReload);
};
scwin.fn_validCheck = function() {
    var a = 0;
    for (var i = 0; i < scwin.arrOPEN.length; i++) {
        if (eval("checkbox_OPEN" + scwin.arrOPEN[i]).checked) {
            a++;
        }
    }
    if (a == 0) {
        $c.win.alert("열람상태를 선택해 주세요.");
        checkbox_OPEN0.focus();
        return false;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_SrchDay).length < 8) {
        $c.win.alert("일자를 올바르게 입력해 주세요.");
        edt_SrchDay.focus();
        return false;
    }
    return true;
};
scwin.fn_getCheckedOPEN = function() {
    var text = "";
    for (var i = 0; i < scwin.arrOPEN.length; i++) {
        if (eval("checkbox_OPEN" + scwin.arrOPEN[i]).checked) {
            text.setValue(i + "");
            i = scwin.arrOPEN.length;
        }
    }
    return text;
};
scwin.fn_checkbox_OPEN = function(flag) {
    if (flag == "0") {
        //전체
        if (checkbox_OPEN0.checked) {
            for (var i = 1; i < scwin.arrOPEN.length; i++) {
                eval("checkbox_OPEN" + scwin.arrOPEN[i]).setValue(1);
            }
        } else {
            for (var i = 1; i < scwin.arrOPEN.length; i++) {
                eval("checkbox_OPEN" + scwin.arrOPEN[i]).setValue(0);
            }
        }
    } else {
        var a = 0;
        for (var i = 1; i < scwin.arrOPEN.length; i++) {
            if (!eval("checkbox_OPEN" + scwin.arrOPEN[i]).checked) {
                a++;
            }
        }
        if (a == 0) {
            checkbox_OPEN0.setValue(1);
        } else {
            checkbox_OPEN0.setValue(0);
        }
    }
};
scwin.fn_Search = function() {
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);
    if (!scwin.fn_validCheck()) return;
    var url = "/MktActNotice.do?method=listJntDisclsRead" + "&ACPT_DATE=" + scwin.gDate + "&EMP_NO=" + js_emp_no + "&READ_YN=" + scwin.fn_getCheckedOPEN() + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclStudyList.DataID = encodeURI(url);
    dts_DsclStudyList.reset();
};
scwin.fn_SearchAlarm = function(pReload) {
    if (!scwin.fn_validCheck()) return;
    var url = "/MktActNotice.do?method=listJntDisclsAlarm" + "&ACPT_DATE=" + scwin.gDate + "&EMP_NO=" + js_emp_no + "&READ_YN=" + scwin.fn_getCheckedOPEN();
    if (pReload != 'Y') {
        //자동refresh일때는 로그 없앰
        url = url + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }
    dts_Alarm.DataID = encodeURI(url);
    dts_Alarm.reset();
};


// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclStudyList.getCellData(eval(obj), "ACPT_NO");
    //gDisclsDocNo  = dts_DsclStudyList.NameString(eval(obj),"DISCLS_DOC_NO");
    //gMainFormCd = dts_DsclStudyList.NameString(eval(obj),"FORM_CD");
    //gFormVer = dts_DsclStudyList.NameString(eval(obj),"FORM_VER");
    scwin.gIsurCd = dts_DsclStudyList.getCellData(eval(obj), "ISUR_CD");
    //gSndlocTpCd = dts_DsclStudyList.NameString(eval(obj),"SNDLOC_TP_CD");
    //alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd+","+ gSndlocTpCd +"="+ gDisclsDocNo);

};
scwin.setAlarm = function() {
    pnl_alert.style.display = 'none';
    if (js_dep_cd == "2430" || js_dep_cd == 'ZSYS') scwin.isBondsTeam = true;
    if (scwin.isBondsTeam) {
        pnl_bonds.style.display = '';
        pnl_alert.innerHTML = "<embed src='/common/form_procs_132.wav' name='alertSound1' autostart='false'>" + "<embed src='/common/form_procs_133.wav' name='alertSound2' autostart='false'>" + "<embed src='/common/form_procs_134.wav' name='alertSound3' autostart='false'>";
    } else {
        pnl_bonds.style.display = 'none';
    }
};
scwin.alarmCheck = function(obj) {
    if (scwin.isAlarm) {
        //알람 on 상태
        if (obj.getTotalRow() > 0) {
            var soundTimeout = null;
            for (var i = 1; i <= obj.getTotalRow(); i++) {
                var alarm_tp_cd = obj.getCellData(i, "ALARM_TP_CD");
                soundTimeout = setTimeout("playAlarm(" + alarm_tp_cd + ")", 5000 * i);
            }
            clearTimeout(soundTimeout); //쿼리에서 데이터 한줄 추가해서 들고오도록 함(마지막 알림 안나옴)

        }
    }
};
scwin.playAlarm = function(n) {
    eval("alertSound" + n).play();
};
scwin.fn_SetHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LIST_JNT_DISCLS_READ_INOUT";
    dts_Save.reset();
};
scwin.fn_SaveHist = function(gAcptNo) {
    if (scwin.gAcptNo == null || scwin.gAcptNo == "") {
        return;
    } else {
        scwin.fn_SetHeader();
        dts_Save.insertRow();
        dts_Save.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_Save.setCellData(1, "EMP_NO", js_emp_no);
        trs_Save.Action = "/MktActNotice.do?method=saveJntDisclsReadHist&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
        trs_Save.Post();
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        scwin.fn_SaveHist(scwin.gAcptNo); //공시뷰어 열람이력 저장

        scwin.gMoveToPosition = row;
        scwin.fn_Search();
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.search_yn = true;
    fn_CheckCond('N');
};
scwin.dts_Alarm_OnLoadError = function() {
    $c.stf.alert_error(dts_Alarm);
};
scwin.dts_Alarm_OnLoadCompleted = function(rowcount) {
    if (scwin.isBondsTeam) scwin.alarmCheck(dts_Alarm);

    //if(dts_Alarm.CountRow > 1 || alarmCnt <= 1) {
    scwin.fn_Search();
    //}

};
scwin.dts_DsclStudyList_OnLoadError = function() {
    $c.stf.alert_error(dts_DsclStudyList);
    scwin.gMoveToPosition = 0;
    scwin.search_yn = false;
    $c.cm.CloseWin(0, grd_Grid);
};
scwin.dts_DsclStudyList_OnLoadCompleted = function(rowcount) {
    if (dts_DsclStudyList.errorMsg) {
        $c.win.alert(dts_DsclStudyList.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
        dts_DsclStudyList.setRowPosition(scwin.gMoveToPosition, 0);
    }
    scwin.gMoveToPosition = 0;
    scwin.search_yn = false;
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var file_name = "주권공시처리현황";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
    //grd_Grid.GridToExcel("주권공시처리현황", "", "8");

};
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    scwin.fn_Init();

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_StartSearch();
};
scwin.chk_alarm_onclick = function() {
    if (chk_alarm.checked) {
        scwin.isAlarm = true;
    } else {
        scwin.isAlarm = false;
    }
};
scwin.checkbox_OPEN0_onclick = function() {
    scwin.fn_checkbox_OPEN(0);
};
scwin.checkbox_OPEN1_onclick = function() {
    scwin.fn_checkbox_OPEN(1);
};
scwin.checkbox_OPEN2_onclick = function() {
    scwin.fn_checkbox_OPEN(2);
};
